use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-descriptor-chunks176";
fn h(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn main(){assert!(!Path::new(R).join("review-count-correction.json").exists());let p=format!("{R}/review.json");let bytes=fs::read(&p).unwrap();let mut v:Value=serde_json::from_slice(&bytes).unwrap();assert_eq!(v["passed"],true);assert_eq!(v["native_core_tests"],128);
 let core=fs::read(format!("{R}/native/core-tests/stdout.log")).unwrap();let text=std::str::from_utf8(&core).unwrap();assert!(text.contains("test result: ok. 127 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out"));let selected=text.lines().filter(|l|l.starts_with("test ")&&l.contains("msm::descriptor_chunks::")).collect::<Vec<_>>();assert_eq!(selected.len(),2);assert!(selected.iter().all(|l|l.ends_with(" ... ok")));
 fs::write(format!("{R}/review-before-count-correction.json"),&bytes).unwrap();v["native_core_tests"]=json!(127);v["reapplied_original_oracle_populations"]=json!(2);v["new_mathematical_test_populations"]=json!(0);let new=serde_json::to_vec_pretty(&v).unwrap();fs::write(p,&new).unwrap();
 let note=json!({"scope":"metadata only; original reviewer already asserted 127 passing tests but inherited its output field128; correct field against same test receipt, with no test/capture/review rerun","old_review_sha256":h(&bytes),"new_review_sha256":h(&new),"core_stdout_sha256":h(&core),"old_native_core_tests":128,"corrected_native_core_tests":127,"reapplied_original_oracle_populations":2,"all_other_review_fields_unchanged":true});fs::write(format!("{R}/review-count-correction.json"),serde_json::to_vec_pretty(&note).unwrap()).unwrap();println!("Corrected inherited review count128 to actual127; original preserved, no successful stage rerun");}
